    if(event.code==='Escape'&&chatOpen){event.preventDefault();event.stopImmediatePropagation();closeChat(false);if(mode==='playing')pause();else canvas.focus({preventScroll:true});return;}
    if(editing){if(event.code==='Escape'&&mode==='settings'){event.preventDefault();event.stopImmediatePropagation();closeSettings();}return;}
