    if(canvas.width===pixelWidth&&canvas.height===pixelHeight&&vignetteImage.width===pixelWidth&&vignetteImage.height===pixelHeight)return;
    canvas.width=pixelWidth;canvas.height=pixelHeight;vignetteImage.width=pixelWidth;vignetteImage.height=pixelHeight;
    const vc=vignetteImage.getContext('2d');vc.setTransform(dpr,0,0,dpr,0,0);
    const gradient=vc.createRadialGradient(width/2,height/2,Math.min(width,height)*.2,width/2,height/2,Math.max(width,height)*.7);
    gradient.addColorStop(0,'#09120b00');gradient.addColorStop(1,'#040a067a');vc.fillStyle=gradient;vc.fillRect(0,0,width,height);
